dict(id='data-eng', title='Data engineering for AI', short='Data engineering',
 what='Collecting, cleaning, labelling and versioning the data that trains models or grounds them (RAG). Most model quality problems start as data problems.',
 how='<p>A pipeline ingests data, validates it (schema, ranges, duplicates), labels it (people or AI-assisted), splits it, and versions it. <b>Synthetic data</b> fills gaps, but Shumailov et al. (<i>Nature</i>, 2024) showed training on recursively generated data causes <b>model collapse</b>: "irreversible defects" where rare cases disappear.</p>',
 terms=[('Data contract','An agreed schema between data producer and consumer'),('Label noise','Wrong labels in training data'),('Inter-annotator agreement','How often labellers agree'),('Leakage','Test data leaking into training'),('Lineage','Where each record came from'),('Model collapse','Quality loss from training on model-generated data')],
 uses=['Building eval sets','Fine-tuning datasets','Cleaning a RAG document collection'],
 state=['Real human-generated data is becoming more valuable as more web content is AI-generated (Shumailov et al. 2024) [research].'],
 limits=['Label noise.','Personal data inside training data.','Collapse when synthetic data loops back.'],
 qa=['Check eval items never appear in training data.','Audit a random sample of labels.','Tag synthetic vs human data and check the mix.','Check rare classes are still represented.'],
 next=['Safe ratios of synthetic data; provenance labels for web content. <i>Open.</i>'],
 learn=[('Model collapse (Nature 2024)','https://www.nature.com/articles/s41586-024-07566-y')]),

dict(id='mlops', title='MLOps and LLMOps', short='MLOps and LLMOps',
 what='Running models in production the way software is run: automated pipelines, versioning, monitoring, and safe rollouts and rollbacks.',
 how='<p>Google\'s MLOps guide defines three levels: manual (level 0), automated training pipelines with continuous retraining (level 1), and CI/CD for the pipelines themselves (level 2). Sculley et al. (2015) warned of "hidden technical debt" in ML systems: entangled features, hidden feedback loops, and undeclared users of a model\'s output. <b>LLMOps</b> adds pinned prompt and model versions, evals on every change, token cost tracking and tracing.</p>',
 terms=[('Model registry','The record of model versions and their status'),('Continuous training','Retraining on new data automatically'),('Data drift / concept drift','Inputs change / the right answer changes'),('Training-serving skew','Features differ between training and production'),('Shadow / canary deploy','Run the new model silently / for a few users first'),('Eval gate','A release blocked if evals regress')],
 uses=['Retraining fraud models','Rolling out a prompt change safely','Checking a vendor\'s model upgrade'],
 state=['Eval-gated releases and tracing are standard practice for LLM apps [production].'],
 limits=['Drift is found late when labels arrive late.','Vendors can update a model behind the same name.','Configuration sprawl.'],
 qa=['An eval regression must block the deploy.','Check logs: the pinned model version is the one actually called.','Inject shifted data and confirm the drift alert fires.','Roll back prompt and model together and verify both reverted.'],
 next=['Standard eval-as-CI tooling for agents. <i>Open.</i>'],
 learn=[('Google: MLOps continuous delivery','https://docs.cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning'),('Hidden Technical Debt in ML Systems','https://papers.nips.cc/paper_files/paper/2015/hash/86df7dcfd896fcaf2674f757a2463eba-Abstract.html')]),
